public class CajaDiariaDto { public DateOnly Fecha { get; set; } public decimal TotalIngresos { get; set; } public decimal TotalEgresos { get; set; } public decimal Resultado { get; set; } public int CantidadEventosRealizados { get; set; } public List<IngresoCajaDiariaDto> Ingresos { get; set; } = []; public List<EgresoCajaDiariaDto> Egresos { get; set; } = []; public List<EventoRealizadoCajaDto> EventosRealizados { get; set; } = []; public List<MedioPagoCajaDto> DesgloseMediosPago { get; set; } = []; }
